from pathlib import Path
import json,sqlite3
def build(media_root:Path,out:Path):
 c=sqlite3.connect(media_root/'.scene_brain/catalog.db');c.row_factory=sqlite3.Row;titles=[dict(x) for x in c.execute('''select t.display_name,count(s.source_id) cataloged,sum(s.maturity in ('SEARCHABLE','RICH_ATLAS_READY')) searchable,sum(s.maturity='RICH_ATLAS_READY') rich,sum(s.subtitle_status='TRANSCRIPT_REQUIRED') transcript_required from titles t left join sources s on s.title_id=t.title_id and s.present=1 group by t.title_id order by t.display_name''')];c.close();data=json.dumps(titles,separators=(',',':'))
 html='''<!doctype html><meta charset=utf-8><title>Project Preflight</title><style>body{background:#09111f;color:#eef2ff;font:15px system-ui;max-width:1100px;margin:auto;padding:18px}.card{background:#17243a;padding:12px;margin:8px}.bad{color:#fbbf24}.good{color:#4ade80}button,input,select{padding:9px;margin:5px}</style><h1>Production Project Preflight</h1><section><h2>New Project</h2><input type=file id=script><input type=file id=voice><select id=scope></select><button id=check>CHECK PROJECT</button><h2 id=status>NOT READY</h2><div id=needs></div></section><h2>Title Libraries</h2><div id=titles></div><script>const T=__DATA__;scope.innerHTML=T.map(x=>`<option>${x.display_name}</option>`).join('')+`<option>Breaking Bad Universe</option><option>Sheldon Universe</option>`;titles.innerHTML=T.map(x=>`<div class=card><b>${x.display_name}</b><p>Cataloged ${x.cataloged} · Searchable ${x.searchable} · Rich ${x.rich} · Transcript Required ${x.transcript_required}</p><button data-t="${x.display_name}">PREPARE SEARCHABLE LIBRARY</button></div>`).join('');titles.querySelectorAll('button').forEach(b=>b.onclick=()=>needs.textContent=`Preparation for ${b.dataset.t} requires explicit confirmation; opening this page never starts jobs.`);check.onclick=()=>{let x=T.find(z=>z.display_name===scope.value);status.textContent='NOT READY';status.className='bad';needs.textContent=x&&x.searchable===0?`${scope.value}: SEARCHABILITY BOOTSTRAP REQUIRED`:`${scope.value}: source discovery / required Rich Atlas preflight remains required`}</script>'''.replace('__DATA__',data);out.mkdir(parents=True,exist_ok=True);(out/'PROJECT_PREFLIGHT.html').write_text(html,encoding='utf8');(out/'START_PROJECT_PREFLIGHT.bat').write_text('@echo off\r\ncd /d "'+str(out)+'"\r\nstart "PreflightServer" /min python -m http.server 8777 --bind 127.0.0.1\r\ntimeout /t 2 /nobreak >nul\r\nstart "" http://127.0.0.1:8777/PROJECT_PREFLIGHT.html\r\n',encoding='ascii')
